                </div>
                <Button size="sm" className="shrink-0" onClick={() => openComplete(t)}>
                  <CheckCheck className="h-3.5 w-3.5 mr-1" /> Erledigen
                </Button>
              </li>
            ))}
          </ul>
        </CardContent>
      </Card>

      <Dialog open={!!target} onOpenChange={(o) => !o && setTarget(null)}>
