    .eq('role', 'admin')
    .eq('active', true)

  const monthName = format(new Date(year, month - 1), 'MMMM yyyy', { locale: de })
  const title = `Monatsbericht von ${assistantProfile.full_name}`
  const message = `${assistantProfile.full_name} hat den Monatsbericht für ${monthName} abgeschlossen und gesendet.`

  for (const admin of (admins ?? [])) {
    await adminClient.from('notifications').insert({
      tenant_id: ctx.tenantId,
      user_id: admin.id,
      title,
      message,
      type: 'success',
      related_type: 'monthly_report',
      related_id: reportId,
    })
  }
  await sendPushToUsers((admins ?? []).map(a => a.id), title, message)

  // Send email if Resend is configured
  if (process.env.RESEND_API_KEY && process.env.ADMIN_EMAIL) {
    try {
      await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${process.env.RESEND_API_KEY}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          from: process.env.FROM_EMAIL ?? 'noreply@charmely.cloud',
          to: process.env.ADMIN_EMAIL,
          subject: `[Assistenten-App] ${title}`,
          html: `
            <h2>Neuer Monatsbericht</h2>
            <p>${escapeHtml(message)}</p>
            <p>Bitte melden Sie sich an, um den Bericht einzusehen und zu exportieren.</p>
            <p><a href="${process.env.NEXT_PUBLIC_APP_URL ?? 'https://assistenz.charmely.cloud'}/admin/berichte">Zum Bericht</a></p>
          `,
        }),
      })
    } catch (e) {
      console.error('Email send error:', e)
    }
  }

  return NextResponse.json({ success: true })
}

import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'

// Schließt den Onboarding-Wizard ab (Plan: docs/onboarding-plan.md).
// Assistenzkräfte (Wizard-Schritt 2) laufen bewusst NICHT hier durch,
// sondern einzeln über /api/admin/create-user (eigene Fehlerbehandlung
// pro Person, ein ungültiger Eintrag soll den Rest nicht blockieren).
export async function POST(request: Request) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return NextResponse.json({ error: 'Nicht angemeldet' }, { status: 401 })

  const { data: caller } = await supabase.from('profiles').select('role').eq('id', user.id).single()
  if ((caller as { role?: string } | null)?.role !== 'admin') {
    return NextResponse.json({ error: 'Kein Zugriff' }, { status: 403 })
  }

  const body = await request.json()
  const {
    full_name,
    minijob_mode,
    hourly_rate,
    monthly_budget,
    weekly_hours_target,
    reserve_months,
    activities,
  } = body

  if (typeof full_name !== 'string' || full_name.trim().length < 2) {
    return NextResponse.json({ error: 'Bitte einen gültigen Namen angeben.' }, { status: 400 })
  }
  const rate = typeof hourly_rate === 'number' ? hourly_rate : NaN
  if (isNaN(rate) || rate <= 0) {
    return NextResponse.json({ error: 'Ungültiger Stundensatz' }, { status: 400 })
  }

  // 1 · eigener Name
  const { error: profileError } = await supabase
    .from('profiles')
    .update({ full_name: full_name.trim() })
    .eq('id', user.id)
  if (profileError) return NextResponse.json({ error: profileError.message }, { status: 500 })

  // 2 · payroll_settings (insert oder update, wie /api/payroll/settings)
  const payload = {
    hourly_rate: rate,
    minijob_mode: minijob_mode === true,
    monthly_budget: typeof monthly_budget === 'number' ? monthly_budget : 0,
    weekly_hours_target: typeof weekly_hours_target === 'number' ? weekly_hours_target : 15,
    reserve_months: typeof reserve_months === 'number' && reserve_months >= 0 ? reserve_months : 2,
  }
  const { data: existing } = await supabase.from('payroll_settings').select('id').limit(1).single()
  const settingsResult = existing?.id
    ? await supabase.from('payroll_settings').update(payload).eq('id', existing.id)
    : await supabase.from('payroll_settings').insert(payload)
  if (settingsResult.error) {
    return NextResponse.json({ error: settingsResult.error.message }, { status: 500 })
  }

  // 3 · Tätigkeiten (Schritt 5) — freibleibend, Wizard blockiert nicht bei leerer Liste
  const activityNames: string[] = Array.isArray(activities)
    ? [...new Set(activities.map((a: unknown) => String(a).trim()).filter((a: string) => a.length > 0))]
    : []
  if (activityNames.length > 0) {
    const { error: activitiesError } = await supabase
      .from('activities')
      .insert(activityNames.map((name, i) => ({ name, sort_order: i })))
    if (activitiesError) {
      return NextResponse.json({ error: activitiesError.message }, { status: 500 })
    }
  }

  // 4 · Abschluss-Flag (organizations hat keine User-Update-Policy → RPC, siehe 0017)
  const { error: rpcError } = await supabase.rpc('complete_onboarding')
  if (rpcError) return NextResponse.json({ error: rpcError.message }, { status: 500 })

  return NextResponse.json({ success: true })
}

import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { resolveTenantAdmin } from '@/lib/tenant'

export async function POST(request: Request) {
  const ctx = await resolveTenantAdmin()
  if (!ctx) return NextResponse.json({ error: 'Kein Zugriff' }, { status: 403 })

  const body = await request.json()
  const { assistantId, rv_pflicht, kv_pflicht } = body

  if (!assistantId || (typeof rv_pflicht !== 'boolean' && typeof kv_pflicht !== 'boolean')) {
    return NextResponse.json({ error: 'Ungültige Parameter' }, { status: 400 })
  }

  const updatePayload: { rv_pflicht?: boolean; kv_pflicht?: boolean } = {}
  if (typeof rv_pflicht === 'boolean') updatePayload.rv_pflicht = rv_pflicht
  if (typeof kv_pflicht === 'boolean') updatePayload.kv_pflicht = kv_pflicht

  // Tenant explizit scopen (Defense-in-Depth zusätzlich zur RLS) und 0 Zeilen
  // als 404 melden statt still „ok" (M3)
  const supabase = await createClient()
  const { data, error } = await supabase
    .from('profiles')
    .update(updatePayload)
    .eq('id', assistantId)
    .eq('tenant_id', ctx.tenantId)
    .select('id')

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!data?.length) return NextResponse.json({ error: 'Nicht gefunden' }, { status: 404 })
  return NextResponse.json({ ok: true })
}

