  }

  // Beitragssatz: nur übernehmen wenn valide Zahl 0..100, sonst weglassen (DB-Default greift)
  const rate = (v: unknown) =>
    typeof v === 'number' && !isNaN(v) && v >= 0 && v <= 100 ? v : undefined

