import { createClient as createAdminClient } from '@supabase/supabase-js'
import { NextResponse } from 'next/server'
import { format } from 'date-fns'
import { de } from 'date-fns/locale'
import { sendPushToUser } from '@/lib/push'
import type { Database } from '@/types/database'

// Called by a cron job on the last day of each month
// Set up in Vercel as: 0 8 28-31 * * (runs at 8:00 on days 28-31)
// Pro Tenant gruppiert (Architektur §5.3), nur status='active'-Orgs.
export async function POST(request: Request) {
  const authHeader = request.headers.get('authorization')
  if (authHeader !== `Bearer ${process.env.CRON_SECRET}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const adminClient = createAdminClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  )

  const now = new Date()
  const year = now.getFullYear()
  const month = now.getMonth() + 1
  const monthName = format(now, 'MMMM yyyy', { locale: de })

  const { data: orgs } = await adminClient.from('organizations').select('id').eq('status', 'active')
  let remindedTotal = 0

  for (const org of orgs ?? []) {
    const { data: assistants } = await adminClient
      .from('profiles')
      .select('id, email, full_name')
      .eq('tenant_id', org.id)
      .eq('role', 'assistant')
      .eq('active', true)
    if (!assistants?.length) continue

    const sentReports = await adminClient
      .from('monthly_reports')
      .select('assistant_id')
      .eq('tenant_id', org.id)
      .eq('year', year)
      .eq('month', month)
      .eq('status', 'sent')

    const sentIds = new Set((sentReports.data ?? []).map(r => r.assistant_id))

    for (const assistant of assistants) {
      if (sentIds.has(assistant.id)) continue

      await adminClient.from('notifications').insert({
        tenant_id: org.id,
        user_id: assistant.id,
        title: 'Monatsabschluss ausstehend',
        message: `Bitte schließen Sie Ihren Monatsbericht für ${monthName} ab und senden Sie ihn.`,
        type: 'warning',
        related_type: 'monthly_reminder',
        related_id: null,
      } as never)
      await sendPushToUser(assistant.id, 'Monatsabschluss ausstehend', `Bitte den Monatsbericht für ${monthName} abschließen.`, '/zeiterfassung')

      if (process.env.RESEND_API_KEY) {
        try {
          await fetch('https://api.resend.com/emails', {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${process.env.RESEND_API_KEY}`,
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              from: process.env.FROM_EMAIL ?? 'noreply@charmely.cloud',
              to: assistant.email,
              subject: `[Assistenten-App] Monatsabschluss ${monthName} ausstehend`,
              html: `
                <h2>Monatsabschluss ${monthName}</h2>
                <p>Hallo ${assistant.full_name},</p>
                <p>bitte überprüfen und schließen Sie Ihren Monatsbericht für ${monthName} ab.</p>
                <p><a href="${process.env.NEXT_PUBLIC_APP_URL ?? 'https://assistenz.charmely.cloud'}/zeiterfassung">Zur Zeiterfassung</a></p>
              `,
            }),
          })
        } catch (e) {
          console.error('Email error for', assistant.email, e)
        }
      }
      remindedTotal++
    }
  }

  return NextResponse.json({ success: true, reminded: remindedTotal })
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { resolvePlatformAdmin, serviceClient } from '@/lib/platform'

// Superadmin-API für die Mandanten-Verwaltung (Plan docs/mandanten-verwaltung-plan.md):
// Zugriff NUR für platform_admins (Service-Role-Route, Session-basiert).
// GET  → alle Organisationen inkl. Userzahl
// POST → { action: 'set_status' | 'set_plan' | 'set_note', ... }

const setStatusSchema = z.object({
  action: z.literal('set_status'),
  id: z.string().uuid(),
  // 'deleted' bewusst nicht anbieten — Soft-Delete kommt mit eigenem Lösch-Konzept.
  status: z.enum(['active', 'suspended']),
})

const setPlanSchema = z.object({
  action: z.literal('set_plan'),
  id: z.string().uuid(),
  plan: z.enum(['free', 'paid']),
})

const setNoteSchema = z.object({
  action: z.literal('set_note'),
  id: z.string().uuid(),
  notes: z.string().trim().max(2000).nullable(),
})

const bodySchema = z.discriminatedUnion('action', [
  setStatusSchema,
  setPlanSchema,
  setNoteSchema,
])

async function loadState() {
  const db = serviceClient()
  const [{ data: orgs, error: orgsError }, { data: profiles, error: profilesError }] =
    await Promise.all([
      db
        .from('organizations')
        .select('id, name, slug, status, plan, notes, created_at')
        .order('created_at', { ascending: false }),
      db.from('profiles').select('tenant_id'),
    ])
  if (orgsError) throw orgsError
  if (profilesError) throw profilesError

  const userCounts = new Map<string, number>()
  for (const p of profiles ?? []) {
    userCounts.set(p.tenant_id, (userCounts.get(p.tenant_id) ?? 0) + 1)
  }

  const result = (orgs ?? []).map((org) => ({
    ...org,
    user_count: userCounts.get(org.id) ?? 0,
  }))

  return { orgs: result }
}

export async function GET() {
  const ctx = await resolvePlatformAdmin()
  if (!ctx) return NextResponse.json({ error: 'Kein Zugriff' }, { status: 403 })
  try {
    return NextResponse.json(await loadState())
  } catch (e) {
    console.error('Superadmin GET error:', e)
    return NextResponse.json({ error: 'Laden fehlgeschlagen' }, { status: 500 })
  }
}

export async function POST(request: Request) {
  const ctx = await resolvePlatformAdmin()
  if (!ctx) return NextResponse.json({ error: 'Kein Zugriff' }, { status: 403 })

  const parsed = bodySchema.safeParse(await request.json().catch(() => null))
  if (!parsed.success) {
    return NextResponse.json({ error: 'Ungültige Anfrage' }, { status: 400 })
  }
  const body = parsed.data
  const db = serviceClient()

  try {
    if (body.action === 'set_status') {
      if (body.status === 'suspended') {
        // Selbstaussperr-Schutz: Der eigene Mandant des eingeloggten
        // Superadmins darf nicht gesperrt werden.
        const { data: ownProfile, error: ownProfileError } = await db
          .from('profiles')
          .select('tenant_id')
          .eq('id', ctx.userId)
          .maybeSingle()
        if (ownProfileError) throw ownProfileError
        if (ownProfile?.tenant_id === body.id) {
          return NextResponse.json(
            { error: 'Eigener Mandant kann nicht gesperrt werden' },
            { status: 400 }
          )
        }
      }
      const { error } = await db
        .from('organizations')
        .update({ status: body.status })
        .eq('id', body.id)
      if (error) throw error
    } else if (body.action === 'set_plan') {
      const { error } = await db
        .from('organizations')
        .update({ plan: body.plan })
        .eq('id', body.id)
      if (error) throw error
    } else {
      const { error } = await db
        .from('organizations')
        .update({ notes: body.notes })
        .eq('id', body.id)
      if (error) throw error
    }

    return NextResponse.json(await loadState())
  } catch (e) {
    console.error('Superadmin POST error:', e)
    return NextResponse.json({ error: 'Aktion fehlgeschlagen' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { randomBytes } from 'node:crypto'
import { z } from 'zod'
import { resolvePlatformAdmin, serviceClient } from '@/lib/platform'

// Superadmin-API für das Registrierungs-Gating (0013, Architektur §1.6/D4):
// Zugriff NUR für platform_admins (Service-Role-Route, Session-basiert).
// GET  → Modus + alle Codes
// POST → { action: 'create_code' | 'lock_code' | 'set_mode', ... }

const createCodeSchema = z.object({
  action: z.literal('create_code'),
  code: z.string().trim().min(4).max(64).regex(/^[A-Za-z0-9-]+$/,
    'Nur Buchstaben, Zahlen und Bindestriche').optional(),
  max_uses: z.number().int().min(1).max(10000).default(1),
  expires_at: z.string().nullable().optional(),
  note: z.string().trim().max(200).nullable().optional(),
})

const lockCodeSchema = z.object({
  action: z.literal('lock_code'),
  id: z.string().uuid(),
})

const setModeSchema = z.object({
  action: z.literal('set_mode'),
  mode: z.enum(['open', 'code', 'closed']),
})

const bodySchema = z.discriminatedUnion('action', [
  createCodeSchema,
  lockCodeSchema,
  setModeSchema,
])

async function loadState() {
  const db = serviceClient()
  const [{ data: setting }, { data: codes, error }] = await Promise.all([
    db.from('platform_settings').select('value').eq('key', 'registration_mode').maybeSingle(),
    db.from('registration_codes')
      .select('id, code, max_uses, used_count, expires_at, note, created_at')
      .order('created_at', { ascending: false }),
  ])
  if (error) throw error
  const mode = typeof setting?.value === 'string' ? setting.value : 'open'
  return { mode, codes: codes ?? [] }
}

